package com.gtavsource.android;

/** Plain-language help for the modification layer's graphics/performance controls. */
public final class XhynV02SettingHelp {
    private static String explain(String purpose,String effect){return "What it does\n"+purpose+"\n\nPotential performance effect\n"+effect+"\n\nCompare the same scene after changing one setting. Device, driver, memory pressure and temperature affect the result.";}
    public static String get(String key){
        switch(key){
        case "TextureQuality":return explain("Chooses the detail of texture assets used by the game.","Lower textures can reduce memory demand and streaming pressure. They may have little effect on FPS when memory and sampling are not the bottleneck, and surfaces look softer.");
        case "ShadowQuality":return explain("Controls shadow detail and rendering quality.","Lower shadows can reduce GPU work and shadow-map memory, with rougher or less detailed shadows.");
        case "ReflectionQuality":return explain("Controls reflection detail.","Lower reflection quality can reduce GPU and render-target cost, especially in reflective scenes. Reflections become less detailed.");
        case "GrassQuality":return explain("Controls vegetation detail and density used by the quality setting.","Lower grass can reduce geometry, shading and draw-call cost in vegetation-heavy scenes. Bare or indoor scenes may change little.");
        case "ParticleQuality":return explain("Controls quality of effects such as smoke and explosions.","Lower values can reduce GPU work in effect-heavy scenes. Quiet scenes may see little change.");
        case "WaterQuality":return explain("Controls the quality of water effects.","Lower values can reduce GPU work near water. Visible water detail and effects decrease.");
        case "PostFX":return explain("Controls post-processing effects applied to the rendered image.","Lower values can reduce full-screen GPU work and bandwidth. Image effects become simpler.");
        case "Tessellation":return explain("Controls additional geometry detail where the game uses tessellation.","Lower values can reduce GPU geometry work in affected scenes, with less surface detail. Scenes without tessellation may change little.");
        case "MSAA":case "ReflectionMSAA":return explain("Uses multiple samples to smooth object or reflection edges.","Lower sample counts reduce GPU work, bandwidth and render-target memory. Edges become more jagged. The DXVK Force MSAA off override takes priority when enabled.");
        case "SSAO":return explain("Adds contact shading around corners and nearby objects.","Lowering or disabling it can reduce GPU work, with flatter-looking lighting around small objects and corners.");
        case "CityDensity":return explain("Changes the population-density multiplier.","Lower density can reduce simulation, draw calls and streaming demand. Traffic and crowds become less dense.");
        case "PedVarietyMultiplier":case "VehicleVarietyMultiplier":return explain("Changes how much variety the game uses for pedestrians or vehicles.","Lower variety may reduce the number of distinct assets streamed into memory. You will see more repeated models; FPS improvement depends on the current bottleneck.");
        case "LodScale":case "PedLodBias":case "VehicleLodBias":return explain("Changes how much distant world, pedestrian or vehicle detail is retained.","Lower values can reduce geometry and streaming workload. Objects switch detail or appear nearer the camera, making pop-in more visible.");
        case "vsync":return explain("Synchronizes presentation with the display.","Can reduce tearing and improve cadence. It may add latency or constrain output to a supported display cadence. The FPS cap remains a separate setting.");
        case "latency":return explain("Limits how many frames can be queued ahead in the renderer.","A smaller queue may reduce input lag but can lower throughput if the GPU runs out of work. A larger queue can smooth throughput while adding latency.");
        case "match_refresh":return explain("Requests a display refresh rate matching the FPS target or an integer multiple, such as 120 Hz for 40 FPS.","Can improve presentation cadence and avoid unnecessary display refreshes. It does not increase the GPU's rendering capability, and the phone may ignore the request.");
        case "performance_hints":return explain("On supported Android 12+ devices, supplies timing hints for the observed presentation thread. It starts disabled and stops its hint session when the game pauses.","May help Android choose scheduling behavior for sustained work. Results need device testing; the measurement covers that thread's CPU work, not the entire game or GPU.");
        case "turnip_memory":return explain("Automatic uses Turnip's default policy. GMEM uses tile-local rendering storage; SYSMEM favors system-memory rendering. The selected driver must be identified as Turnip.","The faster mode depends on the scene and GPU. Forced modes can increase bandwidth or reduce performance. Keep Automatic as the starting point; other driver families do not use these flags.");
        case "one_ui_workaround":return explain("Applies the scoped Turnip workaround for affected Samsung One UI environments after the selected driver has been identified as Turnip.","A compatibility workaround, with no established FPS benefit. It does not make Turnip compatible with Xclipse or Mali. Restart after changing it.");
        case "dxvk_conf_enabled":return explain("Enables saved dxvk.conf overrides. Turning it off keeps the saved text and uses managed/default values instead.","The effect depends on the values in the file. Editor, tuning controls and effective view show the configuration active for the next launch.");
        case "capture":return explain("Records the next game attempt for up to 20 minutes, then stops automatically. Save report to share exports the data when you choose.","Recording adds diagnostic work and may slightly affect results. It helps investigate slowdowns and crashes; normal play keeps recording off.");
        case "Resolution / render scale":return explain("Scales both render dimensions from the stored base size. 0 restores recorded game dimensions. Positive values retain a 320 × 180 minimum and the label shows the actual size.","Lower resolution can reduce GPU work and render-target memory, with a softer image. CPU-limited scenes may improve little. It changes fixed render size rather than enabling dynamic resolution.");
        case "Use lower graphics settings":return explain("Sets the supported quality overrides to Normal and turns off the listed expensive sampling/shadow effects for the next launch.","Can reduce GPU and memory demand with simpler visuals. It does not guarantee a particular FPS or repair an engine/driver crash.");
        case "Restore graphics quality defaults":return explain("Restores original quality attributes recorded before changes in this update. Resolution, controls and saves remain separate. Older releases did not record their overwritten originals.","Returns to the recorded quality values. This can raise or lower workload depending on the settings you had before.");
        case "Check selected driver: draw and present":return explain("Runs a small graphics test in a separate process and records the driver's identity and reported features.","Helps choose compatible combinations. It does not change normal gameplay performance or certify the full game and texture/readback paths.");
        case "Reset DXVK tuning overrides":return explain("Removes global overrides for the tuning controls. Comments, per-application sections and other managed settings are retained.","Returns those controls to managed/renderer defaults. Sections can still override global values; inspect the effective configuration when comparing results.");
        case "Edit dxvk.conf":return explain("Opens the complete configuration active for the next launch. Save enables the edited overrides. Cancel keeps your saved text. Tuning buttons update this same configuration.","Only the values you change affect performance. Unsupported keys can be ignored by a renderer; use the tuning controls or that renderer's documentation.");
        case "Import dxvk.conf":return explain("Selects a configuration text file and saves its overrides for the selected game folder. The app checks the format and shows unsupported keys.","A config made for another GPU or DXVK build may perform worse or break rendering. Importing a file does not add support for missing driver features.");
        case "View effective configuration":return explain("Shows the same active configuration as the editor, including managed defaults and enabled overrides. Per-application sections remain visible and can take priority.","Viewing the text does not change performance. Use it to check which values will be passed to DXVK at the next launch.");
        case "Clear XHYN shader caches":return explain("Deletes only the app-managed shader caches while the game is closed. Shaders and pipelines must be prepared again on later launches.","Can help investigate a cache problem after changing drivers. It normally makes the next run stutter more; repeatedly clearing a healthy cache is not a speed optimization.");
        case "What happened last time?":return explain("Summarizes the last recorded game attempt and offers relevant troubleshooting steps when the logs contain a recognized error.","This does not change performance or prove the cause of every crash. It helps choose the next setting or driver test.");
        case "Save report to share":return explain("Creates a ZIP with the current attempt's logs, settings and available measurements. Choose where to save it, then share it yourself with support.","Saving a report does not improve FPS. Reports from Record next game provide more information about memory pressure and presentation behavior.");
        case "View technical details":return explain("Shows the underlying startup and runtime error information for troubleshooting.","This is a read-only view and does not change gameplay performance.");
        case "Show advanced DXVK options":case "Hide advanced DXVK options":return explain("Shows specialized compatibility, memory and synchronization controls supported by the selected bundled renderer. Each control has its own information button.","Showing this section changes no settings. Most of these overrides are for a measured bottleneck or rendering problem and may reduce performance or stability.");
        default:
            if(key.startsWith("Rendered FPS cap:"))return explain("Caps rendered output through the active DXVK configuration. Frame generation has separate rendered/output targets.","A sustainable cap can reduce heat and make pacing steadier. It limits maximum output and cannot make the device reach a target it cannot render.");
            return null;
        }
    }
    private XhynV02SettingHelp(){}
}
